import sys

MOD = 1000000007  # type: int

def modpow(n: int, a: int, mod: int = MOD) -> int:
    res = 1
    while a > 0:
        if a & 1:
            res = res * n % mod
        n = n * n % mod
        a >>= 1
    return res

def solve(N: int, A: "List[int]"):
    if N % 2 == 0:
        if not sorted([i for i in range(N - 1, 0, -2)] * 2) == sorted(A):
