            print(modpow(2, len(range(N - 1, 0, -2))))
    else:
        if not sorted([i for i in range(N - 1, 1, -2)] * 2 + [0])  == sorted(A):
            print(0)
        else:
            print(modpow(2, len(range(N - 1, 1, -2))))
    return


