    ''' number: 2 or greater.
    '''
    from collections import OrderedDict

    prime_dict = OrderedDict()
    j = 2
    prime_dict[j] = 0

    for i in range(2, number + 1):
        if all(i % j != 0 for j in prime_dict.keys()):
            prime_dict[i] = 0
    return prime_dict


