import math


def sieve(n):
    is_prime = [True] * (n + 1)
    for i in range(2, math.ceil(math.sqrt(n)) + 1):
        for j in range(i*i, n + 1, i):
            is_prime[j] = False
    return [i for i in range(2, n + 1) if is_prime[i]]


def factor_count(n):
    count = {}
    primes = sieve(n)

    for i in range(2, n + 1):
        num = i
        while num > 1:
            for prime in primes:
                if num % prime == 0:
                    count[prime] = count.get(prime, 0) + 1
                    num //= prime
    ans = 1
    for num in count.values():
        ans = (ans * (num + 1)) % (10 ** 9 + 7)

    return ans

