MOD = 1000000007  # type: int


def solve(N: int):
    from itertools import chain
    from collections import Counter
    from functools import reduce
    pu = PrimeUtil(N+1)
    c = Counter(chain.from_iterable(pu.factor_iter(i) for i in range(2, N+1)))
