def prime_factor(num, prime_dict):
    if num == 1:
        return prime_dict
    if isprime(num):
        prime_dict[num] += 1
        return prime_dict
    if num % 2 == 0:
        prime_dict[2] += 1
        return prime_factor(num // 2, prime_dict)
    elif num % 3 == 0:
        prime_dict[3] += 1
        return prime_factor(num // 3, prime_dict)
    else:
        for i in range(5, int(num ** (1/2))+1):
            if num % i == 0:
                prime_dict[i] += 1
                return prime_factor(num // i, prime_dict)

