def prime_factorization(n :int) -> dict:
    divisor_dic={}
    tmp_num = n

    for i in range(2, int(n**(1/2)+1) ):
        while tmp_num % i == 0:
            divisor_dic.setdefault(i,0)
            divisor_dic[i] += 1

            tmp_num //= i

    if (tmp_num != 1):
        divisor_dic[tmp_num] = 1

    return divisor_dic


