def memoize(function):
    def _memoize(*args, _cache={}):
        if args in _cache:
            return _cache[args]
        result = function(*args)
        _cache[args] = result
        return result
    return _memoize


class Union_find():

    def __init__(self, num):
        self.num = num
        self.par = list(range(num))
        self.rank = [0]*num

    def find(self, x):
        px = self.par[x]
        if px == x:
            return x
        else:
            rx = self.find(px)
            self.par[x] = rx
            return rx

    def union(self, x, y):
        x = self.find(x)
        y = self.find(y)
        if x != y:
            if self.rank[x] > self.rank[y]:
                self.par[y] = x
            else:
                self.par[x] = y
                if self.rank[x] == self.rank[y]:
                    self.rank[y] = self.rank[y] + 1
        return self

    def same(self, x, y):
        return self.find(x) == self.find(y)

    def group_num(self):
        l = set()
        for i in range(self.num):
            l.add(self.find(i))
        return len(l)


class Adjlist():

    def __init__(self, nodes, edges = None):
        self.nodes = nodes
        lis = [set() for i in range(nodes)]
        if edges is not None:
            for edge in edges:
                lis[edge[0]].add(edge[1])
        self.edges = lis

    def add_edge(self, edge):
        self.edges[edge[0]].add(edge[1])
        return self

    def discard_edge(self, edge):
        self.edges[edge[0]].discard(edge[1])
        return self

    def next_set(self, x):
        return self.edges[x]

    def include_edge(self, x, y):
        return y in self.next_set(x)

class Adjlist_weighted():

    def __init__(self, nodes, edges = None):
        self.nodes = nodes
        lis = [{} for i in range(nodes)]
        if edges is not None:
            for edge in edges:
                lis[edge[0]][edge[1]] = edge[2]
        self.edges = lis

    def add_edge(self, edge):
        self.edges[edge[0]][edge[1]] = edge[2]
        return self

    def discard_edge(self, edge):
        del self.edges[edge[0]][edge[1]]
        return self

    def next_set(self, x):
        return self.edges[x].keys()

    def include_edge(self, x, y):
        return y in self.next_set(x)

