def dijk(n,road,start):
  #(町の数,道路のリスト,出発地点)
  dist = [INF for _ in range(n+1)]
  dist[start] = 0
  visit = [False for _ in range(n+1)]
  hq = [(0,start)] #(距離,場所)
  while hq:
    h = heappop(hq)
    dis = h[0]
    pla = h[1]
    if visit[pla]:
      continue
    visit[pla] = True
    for q in road[pla]:
      num = q[0]
      cost = q[1]
      if visit[num] == False:
        if dist[num] > dist[pla] + cost:
          dist[num] = dist[pla] + cost
          heappush(hq,(dist[pla]+cost,num))
  return dist

