  I,J,K = len(A),len(B[0]),len(B)
  c = [[0]*J for _ in range(I)]
  for i in range(I):
    for j in range(J):
      for k in range(K):
        c[i][j] += A[i][k] * B[k][j]
      c[i][j] %= mod
  return c

def arr_pow(x,n,mod):
  #行列の累乗
  #x^n
  y = [[0]*len(x) for _ in range(len(x))]
  for i in range(len(x)):
    y[i][i] = 1
  while n > 0:
    if n & 1:
      y = arr_arr(x,y,mod)
    x = arr_arr(x,x,mod)
    n >>= 1
  return y


