def resolve():
    n, m = map(int, input().split())
    edge = set(tuple(tuple(map(lambda x: int(x) - 1, input().split())) for _ in range(m)))

    dp = [[0] * n for _ in range(1 << n)]
    dp[1][0] = 1
    for S in range(1 << n):
        if not (S & 1):
            continue
        if S == 1:
            for v in range(n):
                if S & (1 << v):
                    continue
                if (0, v) in edge or (v, 0) in edge:
                    dp[S | (1 << v)][v] += dp[S][0]
        else:
            for u in range(1, n):
                if not (S & (1 << u)):
                    continue
                for v in range(n):
                    if S & (1 << v):
                        continue
                    if (u, v) in edge or (v, u) in edge:
                        dp[S | (1 << v)][v] += dp[S][u]
    print(sum(dp[-1]))


