import sys


def solve(sx, sy, tx, ty):
    used = set()
    ans = []
    x, y = sx, sy
    gx, gy = tx, ty
    px, py = sx, sy
    while True:
        path = []
        for nx, ny, d in ((x, y+1, 'U'), (x, y-1, 'D'), (x-1, y, 'L'), (x+1, y, 'R')):
            if not (nx, ny) in used and (nx, ny) != (px, py):
                path.append([abs(nx-gx) + abs(ny-gy), d, (nx, ny)])
        if path == []:
            break
        o = ''
        if  x == gx or y == gy:
            if x == gx:
                o = 'RLUD'
            else:
                o = 'UDRL'
        elif x > gx:
            if y > gy:
                o = 'DLUR'
            else:
                o = 'ULDR'
        else:
            if y > gy:
                o = 'DRUL'
            else:
                o = 'URDL'
        path.sort(key=lambda x: [x[0], o.index(x[1])])
        ans.append(path[0][1])
        x, y = path[0][2]
        used.add((x, y))
        if x == gx and y == gy:
            used.discard((x, y))
            if gx == sx and gy == sy:
                gx, gy = tx, ty
                px, py = sx, sy
            else:
                gx, gy = sx, sy
                px, py = tx, ty
    return ans


def main(args):
    sx, sy, tx, ty = map(int, input().split())
    ans = solve(sx, sy, tx, ty)
    print(*ans, sep='')


if __name__ == '__main__':
    main(sys.argv[1:])

