import copy

def sol1(N, X, A):
  cnt = 0
  for i in range(N-1):
    diff = A[i] + A[i+1] - X
    if diff <= 0: continue

    if A[i+1] >= diff:
      A[i+1] -= diff
    else:
      A[i] = A[i] - (diff - A[i+1])
      A[i+1] = 0
    cnt += diff
  return cnt

def sol2(N, X, A):
  cnt = 0
  for i in range(N-2, -1, -1):
    diff = A[i] + A[i+1] - X
    if diff <= 0: continue

    if A[i] >= diff:
      A[i] -= diff
    else:
      A[i] = 1
      A[i+1] -= diff - (A[i] - 1)

    cnt += diff
  return cnt

