    def __choose(self, n, r):
      p = self.__mod
      return self.__fac[n] * self.__ifac[r] % p * self.__ifac[n-r] % p



    def make_nchoose_table(self, n):
      p = self.__mod
      r = len(self.__fac)-1
      if using_numpy:
