from collections import defaultdict

class Graph:
    def __init__(self):
        self.edges = defaultdict(dict)

    def append_edge(self, sv, ev, weight = 1):
        self.edges[sv][ev] = 1

    def remove_edge(self, sv, ev, weight = 1):
        if sv in self.edges:
            if ev in self.edges[sv]:
                del self.edges[sv][ev]

    def bfs(self, sv, N):
        dist = [-1]*N
        q = deque([])   # キュー
        q.append(sv)
        dist[sv] = 0
        connect_vtxs = []
        root = [-1]*N
        while len(q) > 0:
            p = q.popleft()     # キュー取りだし（先頭）
            connect_vtxs.append(p)
            if p not in self.edges:
                continue
            for ev in self.edges[p].keys():
                if dist[ev] != -1:
                    continue
                q.append(ev)    # キュー追加
                dist[ev] = dist[p] + 1
                root[ev] = p
        return dist, connect_vtxs, root

