def BFS(g, s):
    dist = [float("INF")] * len(g)
    dist[s] = 0
    q, pos = collections.deque([s]), set([s])
    while q:
        s = q.popleft()
        for i in g[s]:
            if i not in pos:
                dist[i] = dist[s] + 1
                pos.add(i)
                q.append(i)
    return dist


def warshall_floyd(g):
    n = len(g)
    d = [[float("INF")] * n for i in range(n)]
    for i in range(n):
        for j, k in g[i]:
            d[i][j] = k
    for i in range(n):
        for j in range(n):
            for k in range(n):
                d[i][j] = min(d[i][j], d[i][k] + d[k][j])
    return d


def dijkstra(g, s):
    n = len(g)
    dist = [float("INF")] * n
    dist[s] = 0
    hq = [(0, s)]
    seen = [False] * n
    while hq:
        v = heapq.heappop(hq)[1]
        seen[v] = True
        for to, cost in g[v]:
            if seen[to] == False and dist[v] + cost < dist[to]:
                dist[to] = dist[v] + cost
                heapq.heappush(hq, (dist[to], to))
    return dist


