from itertools import combinations

def factorize(n):
    b = 2
    fct = []
    while b * b <= n:
        while n % b == 0:
            n //= b
            fct.append(b)
        b = b + 1
    if n > 1:
        fct.append(n)
    return fct

def main():
  N = int(input())
  l = factorize(N)
  n = len(l)
  # print(l)
  Fs = [N]
  for k in range(n+1):
    for comb in combinations(l, k):
      # print(comb)
      if len(comb) == 0:
        continue
      else:
        # print(comb)
        z = 1
        for c in comb:
          z = z * c
        if N % z == 0:
          A = int(N / z)
          B = int(z)
          # print(A,B)
          F = max(len(str(A)),len(str(B)))
          Fs.append(F)
