def f1(a):
    memo = 0
    count = 0
    for i in range(n):
        if i % 2 == 0:
            if a[i] <= 0:
                count += 1 - a[i]
                memo = 1 - a[i]
        else:
            if a[i] >= 0:
                count += a[i] + 1
                memo = -(a[i] + 1)
        if i + 1 < n:
            a[i + 1] = a[i + 1] + a[i] + memo
