        """
        input multi value.
        """
        return [self.ii(t) for _ in range(N)]

    def iml(self, N: int, t: type = int):
        """
        input multi line.
        """
        return [self.il(t) for _ in range(N)]

    def solve(self):
        A = self.ii()
        B = self.ii()
        if A>B:
            return "GREATER"
        if A<B:
            return "LESS"
