            self.par=[i for i in range(n)]
            self.siz=[1]*n

        def root(self,x):
            while self.par[x]!=x:
                self.par[x]=self.par[self.par[x]]
                x=self.par[x]
            return x

        def unite(self,x,y):
            x=self.root(x)
            y=self.root(y)
            if x==y:
