def arr_pow(A, p, mod):
  res = np.eye(A.shape[0], dtype = np.int64)
  while p:
    if p & 1:
      res = np.dot(res, A) % mod
    A = np.dot(A, A) % mod
    p >>= 1
  return res

def dijk(n,road,start):
  #(町の数,道路のリスト,出発地点)
  dist = [INF for _ in range(n+1)]
  dist[start] = 0
  visit = [False for _ in range(n+1)]
  hq = [(0,start)] #(距離,場所)
  while hq:
    h = heappop(hq)
    dis = h[0]
    pla = h[1]
    if visit[pla]:
      continue
    visit[pla] = True
    for q in road[pla]:
      num = q[0]
      cost = q[1]
      if visit[num] == False:
        if dist[num] > dist[pla] + cost:
          dist[num] = dist[pla] + cost
          heappush(hq,(dist[pla]+cost,num))
  return dist

def arr_arr(A,B,mod):
  I,J,K = len(A),len(B[0]),len(B)
  c = [[0]*J for _ in range(I)]
  for i in range(I):
    for j in range(J):
      for k in range(K):
        c[i][j] += A[i][k] * B[k][j]
      c[i][j] %= mod
  return c

def arr_pow(x,n,mod):
  #行列の累乗
  #x^n
  y = [[0]*len(x) for _ in range(len(x))]
  for i in range(len(x)):
    y[i][i] = 1
  while n > 0:
    if n & 1:
      y = arr_arr(x,y,mod)
    x = arr_arr(x,x,mod)
    n >>= 1
  return y

def w_f(N,road):
  #ワ―シャルフロイド法
  #(街の数、道路のリスト)
  dist = [[INF for _ in range(N)] for _ in range(N)]
  for i in range(N):
    dist[i][i] = 0
  for i in range(N):
    for k in road[i+1]:
      dist[i][k[0]-1] = min(k[1],dist[i][k[0]-1])
  for k in range(N):
    for i in range(N):
      for j in range(N):
        dist[i][j] = min(dist[i][j],dist[i][k]+dist[k][j])
  return dist
