def S(n, k, modz):
    sumz = 0

    sign = 1 if (k & 0x01 == 0) else -1
    for i in range(k + 1):
        if sign > 0:
            sumz = (sumz + (nCk(k, i, modz) * mypow(i, n, modz)) % modz) % modz
        else:
            sumz = (sumz + (modz - nCk(k, i, modz) * mypow(i, n, modz) % modz)) % modz

        sign = -sign
    return fact_inv[k] * sumz % modz

