def check_bipartiteness(n_vertices, edges):
    ds = DisjointSet(2 * n_vertices)

    for a, b in edges:
        ds.union(a, b + n_vertices)
        ds.union(b, a + n_vertices)

    next_color = 0
    color = [-1] * (2 * n_vertices)
    for v in range(n_vertices):
        ra = ds.find(v)
        rb = ds.find(v + n_vertices)
        if ra == rb:
            return None
        if color[ra] < 0:
            color[ra] = next_color
            color[rb] = next_color + 1
            next_color += 2
        color[v] = color[ra]
        color[v + n_vertices] = color[rb]
    return color[:n_vertices]


def small_range_duplicate(a):
    MASK = (1 << 32) - 1
    n = len(a)
    left = [i - 1 for i in range(n + 1)]
    right = [i + 1 for i in range(n + 1)]

    sorted_ind = sorted((~v << 32) | i for i, v in enumerate(a))
    t = 0
    vi = sorted_ind[t]
    i = vi & MASK
    v = ~(vi >> 32)
    while t < n:
        j = i
        l = left[i]
        pi = l
        pv = v
        while v == pv and left[i] == pi:
            pi = i
            t += 1
            if t >= n:
                break
            vi = sorted_ind[t]
            i = vi & MASK
            v = ~(vi >> 32)
        r = right[pi]
        right[l] = r
        while j <= pi:
            nj = right[j]
            left[j] = l
            right[j] = r
            j = nj
        left[r] = l

    return left, right


def small_range(a):
    N = len(a)
    MASK = (1 << 32) - 1
    left = [i - 1 for i in range(N + 1)]
    right = [i + 1 for i in range(N + 1)]
    sorted_ind = sorted((~v << 32) | i for i, v in enumerate(a))
    for v in sorted_ind:
        i = v & MASK
        left[right[-i]] = left[-i]
        right[left[-i]] = right[-i]

    return left, right


def popcnt32(n):
    n = n - ((n >> 1) & 0x55555555)
    n = (n & 0x33333333) + ((n >> 2) & 0x33333333)
    return ((((n + (n >> 4)) & 0x0f0f0f0f) * 0x01010101) >> 24) & 0xff


def popcnt64(n):
    n = n - ((n >> 1) & 0x5555555555555555)
    n = (n & 0x3333333333333333) + ((n >> 2) & 0x3333333333333333)
    n = (n + (n >> 4)) & 0x0f0f0f0f0f0f0f0f
    return ((((n + (n >> 32)) & 0xffffffff) * 0x01010101) >> 24) & 0xff


def popcnt(n):
    if n < 1 << 32:
        return popcnt32(n)
    elif n < 1 << 64:
        return popcnt64(n)
    else:
        return sum(c == '1' for c in bin(n))


def reverse_bits32(x):
    x = ((x & 0x55555555) << 1) | ((x & 0xAAAAAAAA) >> 1)
    x = ((x & 0x33333333) << 2) | ((x & 0xCCCCCCCC) >> 2)
    x = ((x & 0x0F0F0F0F) << 4) | ((x & 0xF0F0F0F0) >> 4)
    x = ((x & 0x00FF00FF) << 8) | ((x & 0xFF00FF00) >> 8)
    return ((x & 0x0000FFFF) << 16) | ((x & 0xFFFF0000) >> 16)


