def answer(lines):
    def input():
        return lines.popleft()
    def mi_input():
        return map(int, input().split())
    def lw_input(n):
        returns = []
        for _ in range(n):
            returns.append(list(mi_input()))
        return returns

    def lh_input(n, m):
        returns = [[] for _ in range(n)]
        for j in range(m):
            _l = list(mi_input())
            for i in range(n):
                returns[i].append(_l[i])
        return returns

    # ☆★☆ ここに解答の処理を記述する ☆★☆
    # 入力は lines（deque）に詰め込んでいるので input() の代わりに lines.popleft() などを使えばよい
    n, k = mi_input()
    l = sorted(lw_input(1)[0])
    print(sum(l[::-1][:k]))


