      self.__depth = self.__lv = lv = [None]*self.__N; lv[src] = 0 # depth in tree, or level in general graph.
      self.__dist = dist = [inf]*self.__N; dist[src] = 0
      self.__parent = par = [None]*self.__N; par[src] = src
      q = deque([src])
      while q:
