    def bellman_ford(V, G, i):
        INF = 10**18
        D = [INF] * V
        D[i] = 0
        for _ in range(V):
            update = False
            update_n = False
            for s in range(N):
                for t in G[s].keys():
                    if D[s] != INF and D[t] > D[s] + G[s][t]:
                        D[t] = D[s] + G[s][t]
                        update = True
                        if t == V - 1:
                            update_n = True
            if not update:
                return -D[-1]
            if _ == V - 1:
                if update_n:
                    return INF
                else:
                    return -D[-1]

    G = [{i: 0} for i in range(N)]
    for a, b, c in zip(A, B, C):
        G[a][b] = c
    d = bellman_ford(N, G, 0)
    if d < 10**18:
        print(d)
    else:
        print('inf')


