class DiGraph():
    def __init__(self, n):
        self.n = n
        self.graph = [[] for _ in range(n)]
        self.rev = [[] for _ in range(n)]

    def add_edge(self, fr, to, c, idx=1):
        self.graph[fr - idx].append((to - idx, c))
        self.rev[to - idx].append((fr - idx, c))

    def bellman_ford(self, s, t=None):
        dist = [-INF] * self.n
        dist[s] = 0
        prev = [None] * self.n
        update = True
        for i in range(self.n):
            update = False
            for v, g in enumerate(self.graph):
                for adj, cost in g:
                    if dist[v] != -INF and dist[v] + cost > dist[adj]:
                        dist[adj] = dist[v] + cost
                        prev[adj] = v
                        update = True
            if not update:
                if t is None: return dist
                if dist[t] == -INF: return INF, []
                v = t
                path = [v]
                while v != s:
                    v = prev[v]
                    path.append(v)
                return dist[t], path[::-1]
        if t is None: return []
        negative_cycle = [0 for _ in range(self.n)]
        for i in range(self.n):
            for v, g in enumerate(self.graph):
                for adj, cost in g:
                    if dist[v] != -INF and dist[v] + cost > dist[adj]:
                        dist[adj] = dist[v] + cost
                        prev[adj] = v
                        negative_cycle[adj] = True
        if not negative_cycle[t]:
            if dist[t] == -INF: return INF, []
            v = t
            path = [v]
            while v != s:
                v = prev[v]
                path.append(v)
            return dist[t], path[::-1]
        return -1, []

