        update = False
        for v in range(n*2):
            v%=n
            # dist[v] == INFなら緩和しない
            if dist[v] == INF: continue
            for e in graph.output(v):
                if i == n-1:
                    if dist[e[0]]  > dist[v] +e[1]:
                        dist[e[0]] = -1*INF
                else:
                    if dist[e[0]]  > dist[v] +e[1]:
                        dist[e[0]] = dist[v] +e[1]
