def solve():
    W, H, N = tuple(map(int, input().split()))

    R = []
    for _ in range(N):
        R.append(tuple(map(int, input().split())))

    # print("W, H, N", W, H, N)
    # print(R)

    table = [[0 for x in range(W + 1)] for y in range(H + 1)]

    for x, y, a in R:
        # print(x, y, "|", a)
        y = H - y
        # 1: x より小さい左側の領域
        if a == 1:
            for yi in range(H + 1):
                for xi in range(x):
                    table[yi][xi] = "*"
        # 2: x より大きい右側の領域
        elif a == 2:
            for yi in range(H + 1):
                for xi in range(x + 1, W + 1):
                    table[yi][xi] = "*"
        # 3: 長方形の H < y を塗る
        elif a == 3:
            for yi in range(y + 1, H + 1):
                for xi in range(W + 1):
                    table[yi][xi] = "*"
        # 4: 長方形の H > y を塗る
        elif a == 4:
            for yi in range(y - 1, -1, -1):
                for xi in range(W + 1):
                    table[yi][xi] = "*"

    # 白い長方形の左下の座標を探す
    left_bottom = -1, -1
    is_found = False
    for yi in range(H + 1):
        yii = H - yi
        for xi in range(W + 1):
            if table[yii][xi] == 0:
                left_bottom = xi, yi
                is_found = True
                break
        if is_found:
            break

    # 白い長方形の右上の座標を探す
    right_top = -1, -1
    is_found = False
    for yi in range(H + 1):
        for xi in range(W, -1, -1):
            if table[yi][xi] == 0:
                right_top = xi, H - yi
                is_found = True
                break
        if is_found:
            break

    # print(left_bottom, right_top)
    if left_bottom == (-1, -1) and right_top == (-1, -1):
        return 0
    else:
        return (right_top[0] - left_bottom[0]) * (right_top[1] - left_bottom[1])


