import sys


def solve(W, H, N, points):
    grid = [[1]*W for _ in range(H)]
    for x, y, a in points:
        if a == 1:
            for cy, row in enumerate(grid):
                for cx in range(x):
                    row[cx] = 0
        elif a == 2:
            for cy, row in enumerate(grid):
                for cx in range(x, W):
                    row[cx] = 0
        elif a == 3:
            for cy in range(y):
                grid[cy] = [0]*W
        elif a == 4:
            for cy in range(y, H):
                grid[cy] = [0]*W

    return sum([sum(row) for row in grid])


def main(args):
    W, H, N = map(int, input().split())
    points = [[int(i) for i in input().split()] for _ in range(N)]
    ans = solve(W, H, N, points)
    print(ans)


