          f = flow_to_sink(v, min(flow_in, e.capacity))
          if not f: continue
          self.__edges[u][v].capacity -= f
          if u in self.__edges[v]: self.__edges[v][u].capacity += f
          else: self.add_edge(v, u, capacity=f)
          flow_in -= f
          flow += f
        return flow

