class UnionFind:
    def __init__(self, n):
        self.parents = [-1] * n

    def __getitem__(self, item):
        if type(item) == tuple:
            if len(item) == 1:
                return self.size(item[0])
            else:
                self.union(item[0], item[1])
        elif type(item) == slice:
            return self.same(item.start, item.stop)
        else:
            return self.find(item)

    def __len__(self):
        return self.group_count()

    def __pos__(self):
        return self.max_size()

    def __neg__(self):
        return self.min_size()

    def __invert__(self):
        return self.roots()

    def union(self, x, y):
        x, y = self.find(x), self.find(y)
        if x != y:
            if self.parents[x] > self.parents[y]:
                x, y = y, x
            self.parents[x] += self.parents[y]
            self.parents[y] = x

    def find(self, x):
        if self.parents[x] < 0:
            return x
        self.parents[x] = self.find(self.parents[x])
        return self.parents[x]

    def size(self, x):
        return -self.parents[self.find(x)]

    def same(self, x, y):
        return self.find(x) == self.find(y)

    def members(self, x):
        root = self.find(x)
        return [i for i in range(self.n) if self.find(i) == root]

    def roots(self):
        return list(filter(lambda x: x < 0, self.parents))

    def group_count(self):
        return len(self.roots())

    def max_size(self):
        return -min(self.parents)

    def min_size(self):
        return -max(self.roots())

    def append(self, n):
        self.parents += [-1] * n


class Imos:
    def __init__(self, n):
        self.val = [0] * n

    def add(self, x, y, n=None):
        if n is None:
            n = 1
        self.val[x] += n
        if len(self.val) > y + 1:
            self.val[y+1] -= n

    def imos(self):
        for i in range(1, len(self.val)):
            self.val[i] += self.val[i-1]

    def max(self):
        return max(self.val)

    def min(self):
        return min(self.val)


class CS:
    def __init__(self, grid):
        self.cs = grid
        for i0 in range(len(grid)):
            for i1 in range(len(grid[0])):
                if i0 == 0:
                    if i1 == 0:
                        continue
                    self.cs[i0][i1] += self.cs[i0][i1-1]
                else:
                    if i1 == 0:
                        self.cs[i0][i1] += self.cs[i0-1][i1]
                    else:
                        self.cs[i0][i1] += self.cs[i0-1][i1] + self.cs[i0][i1-1] - self.cs[i0-1][i1-1]

    def sum(self, start_0, start_1, end_0, end_1):
        if start_0 == 0:
            if start_1 == 0:
                return self.cs[end_0][end_1]
            return self.cs[end_0][end_1] - self.cs[end_0][start_1-1]
        if start_1 == 0:
            return self.cs[end_0][end_1] - self.cs[start_0-1][end_1]
        start_0 -= 1
        start_1 -= 1
        return self.cs[end_0][end_1] - self.cs[start_0][end_1] - self.cs[end_0][start_1] + self.cs[start_0][start_1]


