def from_read(dtype=np.int64):
    return np.fromstring(read().decode(), dtype=dtype, sep=' ')

def from_readline(dtype=np.int64):
    return np.fromstring(readline().decode(), dtype=dtype, sep=' ')


class UnionFind:
    def __init__(self, n):
        self.par = np.full(n+1, -1, np.int64)

    def find(self, x):
        if self.par[x] < 0:
            return x
        else:
            self.par[x] = self.find(self.par[x])
            return self.par[x]

    def union(self, x, y):
        x = self.find(x)
        y = self.find(y)

        if x == y: return

        if abs(self.par[x]) < abs(self.par[y]):
            self.par[y] += self.par[x]
            self.par[x] = y
        else:
            self.par[x] += self.par[y]
            self.par[y] = x

#G: グラフ, N: 頂点数, M: 辺数
def kruskal(E, N, M):
    key = E[:, 2]
    idx = np.argsort(key, kind="mergesort")
    E = E[idx]
    uf = UnionFind(N)
    res = 0
    for i in range(M):
        u, v, w = E[i]
        if uf.find(u) == uf.find(v): continue
        res += w
        uf.union(u, v)
    return res

def solve(N, P):
    P = np.hstack((P, np.arange(0, N).reshape(N, 1)))
    E = np.empty((N + N - 2, 3), np.int64)
    x_sort = np.argsort(P[:, 0])
    y_sort = np.argsort(P[:, 1])
    Px = P[x_sort]
    Py = P[y_sort]
    for i in range(N-1):
        E[i] = Px[i, 2], Px[i+1, 2], min(abs(Px[i, 0] - Px[i+1, 0]), abs(Px[i, 1] - Px[i+1, 1]))
        E[-i-1] = Py[i, 2], Py[i+1, 2], min(abs(Py[i, 0] - Py[i+1, 0]), abs(Py[i, 1] - Py[i+1, 1]))
    res = kruskal(E, N, N + N - 2)
    return res

def main():
    N = int(readline())
    P = from_read().reshape(N, 2)
    print(solve(N, P))

