def solve():
    """
    OPT[i][j] : (count, all sum between i and j)
    OPT[i][j] = OPT[i][k]+S[k+1:j+1]
    """
    S = input().strip()
    N = len(S)
    OPT = [
        [0 for _ in range(N)] for _ in range(N)
    ]
    for length in range(N+1):
        for i in range(N-length):
            j = i+length
            OPT[i][j] = [1, int(S[i:j+1])]
            for l in range(i, j):
                OPT[i][j][0] += OPT[i][l][0]
                OPT[i][j][1] += OPT[i][l][1]+OPT[i][l][0]*int(S[l+1:j+1])
    return OPT[0][N-1][1]


