# 「#」がもの、「.」が何もないとすると、一回り周辺を「.」で埋める
# マップを作成する。「.」が0で「#」が1を表す
def create_map(H, W):
    f = sys.stdin
    S = [f.readline().rstrip() for i in range(H)]
    tbl = [[0] * (W + 2) for i in range(H + 2)]
    for i in range(1, H + 1):
        for j in range(1, W + 1):
            tbl[i][j] = 0 if S[i - 1][j - 1] == "." else 1
    return tbl

